int n = 5;
for (int i = 1; i <= n; i++) {
    for (int s = 1; s <= n - i; s++) {
        printf(" ");
    }
    for (int k = 1; k <= i; k++) {
        printf("%d", k);
    }
    for (int k = i - 1; k >= 1; k--) {
        printf("%d", k);
    }
    printf("\n");
}

